import fs from 'fs';
import path from 'path';
import {
  MAX_DOC_CONTENT,
  createDocument,
  docAudience,
  findOwnedDoc,
  findResearchDoc,
  isTextEditable,
  researchAudience,
  saveNewVersion,
  saveResearchVersion,
} from './doc-store.mjs';
import { getUserFilesDir } from './paths.mjs';
import { broadcastToUsers } from '../routes/_helpers/broadcast.mjs';
import { getUser } from '../routes/_helpers.mjs';

const MAX_CLIP_TEXT = 20_000;

function readIndex(file) {
  try {
    const value = JSON.parse(fs.readFileSync(file, 'utf8'));
    return Array.isArray(value) ? value : [];
  } catch { return []; }
}

export function listBrowserClipTargets(userId) {
  const docsDir = getUserFilesDir(userId, 'documents');
  const researchDir = getUserFilesDir(userId, 'research');
  const docs = readIndex(path.join(docsDir, 'docs-index.json'))
    .filter(isTextEditable)
    .map(doc => ({
      id: `documents:${doc.id}`,
      kind: 'document',
      label: doc.filename,
      description: String(doc.description || '').slice(0, 200),
      version: doc.versions?.at(-1)?.n ?? 1,
    }));
  const research = readIndex(path.join(researchDir, 'index.json'))
    .map(doc => ({
      id: `research:${doc.id}`,
      kind: 'research',
      label: doc.title || doc.id,
      description: Array.isArray(doc.tags) ? doc.tags.slice(0, 8).join(', ') : '',
      version: doc.versions?.at(-1)?.n ?? 1,
    }));
  return [...docs, ...research].sort((a, b) => a.label.localeCompare(b.label));
}

function cleanLine(value, fallback) {
  const line = String(value || '').replace(/[\r\n\0]+/g, ' ').replace(/\s+/g, ' ').trim();
  return (line || fallback).slice(0, 300);
}

function formatClip(capture) {
  if (!capture || typeof capture !== 'object') throw new Error('clip capture is required');
  const rawUrl = String(capture.url || '').trim();
  let parsed;
  try { parsed = new URL(rawUrl); } catch { throw new Error('clip URL is invalid'); }
  if (!['http:', 'https:'].includes(parsed.protocol)) throw new Error('clip URL must use http or https');
  parsed.username = '';
  parsed.password = '';
  // Query strings often contain account/search identifiers. A clip is a
  // citation, not a replay token, so retain only the origin and path.
  parsed.search = '';
  parsed.hash = '';
  const url = parsed.toString().replace(/>/g, '%3E');
  const title = cleanLine(capture.title, parsed.hostname);
  const kind = capture.kind === 'selection' ? 'Selection' : 'Page excerpt';
  const text = String(capture.text || '').replace(/\0/g, '').trim().slice(0, MAX_CLIP_TEXT);
  if (!text) throw new Error('clip has no text');
  const quoted = text.split('\n').map(line => `> ${line}`).join('\n');
  return [
    `## ${title}`,
    '',
    `- Source: <${url}>`,
    `- Saved: ${new Date().toISOString()}`,
    `- Capture: ${kind}`,
    '',
    quoted,
  ].join('\n');
}

function notify(userId, target, version, byName) {
  try {
    const audience = target.kind === 'research'
      ? researchAudience(userId, target.doc.id, userId)
      : docAudience(target.doc, userId);
    broadcastToUsers(audience, {
      type: 'doc_changed',
      docId: target.doc.id,
      filename: target.kind === 'research' ? (target.doc.title || target.doc.id) : target.doc.filename,
      source: target.kind === 'research' ? 'research' : undefined,
      action: 'updated',
      version,
      previousVersion: version > 1 ? version - 1 : null,
      byName,
    });
  } catch (e) {
    console.warn('[browser-clip] doc_changed broadcast failed:', e.message);
  }
}

function resolveOwnedTarget(userId, rawId) {
  const value = String(rawId || '');
  if (value.startsWith('documents:')) {
    const id = value.slice('documents:'.length);
    const doc = findOwnedDoc(userId, id);
    return doc && isTextEditable(doc) ? { kind: 'document', doc } : null;
  }
  if (value.startsWith('research:')) {
    const id = value.slice('research:'.length);
    const doc = findResearchDoc(userId, id);
    return doc ? { kind: 'research', doc } : null;
  }
  return null;
}

export async function appendBrowserClip(userId, { targetId, newDocumentName, capture } = {}) {
  const fragment = formatClip(capture);
  const byName = getUser(userId)?.name || 'OE Browser Clip';

  if (targetId === 'new' || (!targetId && newDocumentName)) {
    const cleanName = cleanLine(newDocumentName, 'Browser research');
    const filename = path.extname(cleanName) ? cleanName : cleanName + '.md';
    const created = await createDocument({
      ownerId: userId,
      filename,
      content: `# ${cleanName.replace(/\.[^.]+$/, '')}\n\n${fragment}\n`,
      description: 'Research collected with OE Bridge',
      byName,
    });
    if (created.error) throw new Error(created.error);
    notify(userId, { kind: 'document', doc: created.doc }, 1, byName);
    return { ok: true, created: true, targetId: `documents:${created.doc.id}`, label: created.doc.filename, version: 1 };
  }

  const target = resolveOwnedTarget(userId, targetId);
  if (!target) throw new Error('clip target was not found or is not editable by this user');
  let current = '';
  let expectedVersion = target.doc.versions?.at(-1)?.n ?? 1;
  if (target.kind === 'research') {
    current = fs.readFileSync(path.join(getUserFilesDir(userId, 'research'), path.basename(target.doc.filename)), 'utf8');
  } else {
    current = fs.readFileSync(path.join(getUserFilesDir(userId, 'documents'), target.doc.id + target.doc.ext), 'utf8');
  }
  const separator = current.trim() ? '\n\n' : '';
  const content = `${current.replace(/\s*$/, '')}${separator}${fragment}\n`;
  if (content.length > MAX_DOC_CONTENT) throw new Error('the selected document is too large for another clip');

  const result = target.kind === 'research'
    ? await saveResearchVersion({
        userId, docId: target.doc.id, content, source: 'user', by: userId, byName,
        note: `Clipped ${cleanLine(capture?.title, 'browser page')}`, expectedVersion,
      })
    : await saveNewVersion({
        ownerId: userId, docId: target.doc.id, content, source: 'user', by: userId, byName,
        note: `Clipped ${cleanLine(capture?.title, 'browser page')}`, expectedVersion,
      });
  if (result.error) throw new Error(result.error);
  notify(userId, target, result.n, byName);
  return {
    ok: true,
    created: false,
    targetId,
    label: target.kind === 'research' ? (target.doc.title || target.doc.id) : target.doc.filename,
    version: result.n,
  };
}

/**
 * Model catalog for the SuperGrok / xAI OAuth provider (xai-oauth).
 *
 * Prefer a live list from the Grok CLI proxy when a token is present; fall back
 * to a curated static list so the Settings UI works during setup.
 */

import fs from 'fs';
import path from 'path';
import { ensureFreshToken, GROK_CLI_PROXY_BASE, GROK_CLI_HEADERS, isConnected } from './xai-oauth-auth.mjs';
import { fetchXaiCLI } from './xai-client-compat.mjs';
import { getUserDir, atomicWriteSync } from '../routes/_helpers.mjs';
import { modelCapabilityFields } from './model-capabilities.mjs';

const CACHE_TTL_MS = 6 * 60 * 60 * 1000;

/** Curated defaults when live catalog is unavailable. Text chat models only. */
export const XAI_OAUTH_FALLBACK_MODELS = [
  { id: 'grok-4.5', name: 'Grok 4.5' },
  { id: 'grok-4.3', name: 'Grok 4.3' },
  { id: 'grok-build-0.1', name: 'Grok Build 0.1' },
  { id: 'grok-4.20-0309-reasoning', name: 'Grok 4.20 Reasoning' },
  { id: 'grok-4.20-0309-non-reasoning', name: 'Grok 4.20 Fast' },
];

function cachePath(userId) {
  return path.join(getUserDir(userId), 'xai-oauth-models.json');
}

function readCache(userId) {
  try {
    const raw = JSON.parse(fs.readFileSync(cachePath(userId), 'utf8'));
    if (!Array.isArray(raw.models)) return null;
    return raw;
  } catch {
    return null;
  }
}

function writeCache(userId, models) {
  const p = cachePath(userId);
  fs.mkdirSync(path.dirname(p), { recursive: true });
  atomicWriteSync(p, JSON.stringify({ version: 2, fetchedAt: Date.now(), models }, null, 2));
}

function isMediaOnly(id) {
  return /^grok-imagine-(?:image|video)/i.test(id)
    || /\b(?:image|video)\b/i.test(id) && /imagine/i.test(id);
}

function annotate(model) {
  const id = model.id ?? model.slug ?? model.name;
  if (!id || isMediaOnly(String(id))) return null;
  const displayName = model.name ?? model.displayName ?? model.display_name ?? id;
  const knownChatModel = /^grok-(?:\d|build-)/i.test(id)
    && !/\b(?:image|video|imagine|voice|audio)\b/i.test(id);
  return {
    id,
    name: displayName,
    displayName,
    contextLen: model.contextLen ?? model.context_window ?? model.max_context_window ?? null,
    ...modelCapabilityFields('xai-oauth', id, model),
    // Image tool support does not make a Grok chat model media-only. These
    // flags prevent the generic catalog's capability heuristic rejecting it.
    ...(knownChatModel ? { textModelKnown: true, textModel: true } : {}),
    aliases: model.aliases ?? model.alias ?? [],
    supportedReasoningLevels: model.supportedReasoningLevels
      ?? model.supported_reasoning_levels
      ?? model.reasoning_efforts
      ?? null,
    defaultReasoningLevel: model.defaultReasoningLevel
      ?? model.default_reasoning_level
      ?? model.reasoning_effort
      ?? null,
  };
}

async function fetchLiveModels(userId) {
  const auth = await ensureFreshToken(userId);
  const headers = {
    'Accept': 'application/json',
    'Authorization': `Bearer ${auth.access_token}`,
    ...GROK_CLI_HEADERS,
  };
  const url = `${GROK_CLI_PROXY_BASE.replace(/\/$/, '')}/models`;
  const res = await fetchXaiCLI(url, { headers, signal: AbortSignal.timeout(15000) }, { userId });
  if (!res.ok) {
    // Some proxy builds have no /models — fall through to static.
    throw new Error(`xAI OAuth models ${res.status}: ${(await res.text()).slice(0, 200)}`);
  }
  const data = await res.json();
  const raw = Array.isArray(data?.data) ? data.data
    : Array.isArray(data?.models) ? data.models
    : Array.isArray(data) ? data
    : [];
  const models = raw.map(annotate).filter(Boolean)
    .sort((a, b) => String(a.name).localeCompare(String(b.name)));
  if (!models.length) throw new Error('xAI OAuth models list empty');
  return models;
}

function fallbackAnnotated() {
  return XAI_OAUTH_FALLBACK_MODELS.map(m => annotate(m)).filter(Boolean);
}

function annotateCached(model) {
  if (model.modelMetadata) return annotate(model);
  const { supportsVision, supportsImageGeneration, ...legacy } = model;
  return annotate(legacy);
}

/**
 * @param {string} userId
 * @param {{ refresh?: boolean, strict?: boolean }} [opts]
 * @returns {Promise<Array<{id, name, displayName, ...}>>}
 */
export async function listXaiOAuthModels(userId, { refresh = false, strict = false } = {}) {
  if (!isConnected(userId)) {
    if (strict) return [];
    return fallbackAnnotated();
  }

  if (!refresh) {
    const cached = readCache(userId);
    if (cached?.version === 2 && Array.isArray(cached.models) && cached.models.length
        && (Date.now() - (cached.fetchedAt || 0)) < CACHE_TTL_MS) {
      return cached.models.map(annotateCached).filter(Boolean);
    }
  }

  try {
    const models = await fetchLiveModels(userId);
    writeCache(userId, models);
    return models;
  } catch (e) {
    if (strict) throw e;
    const cached = readCache(userId);
    if (cached?.models?.length) return cached.models.map(annotateCached).filter(Boolean);
    return fallbackAnnotated();
  }
}

// @ts-check
/**
 * OAuth 2.1 + PKCE provider for MCP, implementing the SDK's
 * OAuthClientProvider interface with file-backed encrypted storage.
 *
 * Tokens and PKCE state live at:
 *   users/<ownerId>/mcp-oauth-<serverId>.json
 * encrypted with the same envelope as the rest of the per-user secrets.
 *
 * Flow:
 *   1. UI calls POST /api/mcp/servers/:id/oauth/start.
 *      Route instantiates this provider and calls SDK's `auth(provider, {serverUrl})`.
 *      SDK discovers metadata, runs Dynamic Client Registration (if supported),
 *      generates PKCE, and calls `provider.redirectToAuthorization(url)`.
 *      We capture the URL here. Route returns `{authUrl, state}` to UI.
 *   2. UI opens authUrl in a popup. User authorizes on the provider.
 *      Provider redirects to `<oe>/api/mcp/oauth/callback?code=...&state=...`.
 *   3. Callback route looks up the (ownerId, serverId) from the in-memory
 *      pending-state map, instantiates the provider, and calls
 *      `auth(provider, {serverUrl, authorizationCode: code})`.
 *      SDK exchanges code for tokens; `provider.saveTokens()` persists them.
 *   4. Future HTTP requests inject the bearer token automatically because
 *      StreamableHTTPClientTransport was given the same provider as `authProvider`.
 *
 * Token refresh is handled transparently by the SDK — it calls
 * `provider.tokens()` before each request and refreshes when the access
 * token nears expiry, calling `provider.saveTokens()` with the new pair.
 *
 * Threat model: tokens are encrypted at rest under the system master key
 * (config-secrets.mjs). The OS account running OE can read them; that's
 * the boundary, same as everywhere else.
 */
import fs from 'fs';
import path from 'path';
import { randomBytes } from 'node:crypto';
import { USERS_DIR } from './paths.mjs';
import { readEncryptedJsonFile, writeEncryptedJsonFile } from './encrypted-file.mjs';

export class OeOAuthProvider {
  constructor({ ownerUserId, serverId, redirectOrigin, scope = '' }) {
    /** @type {string} */
    this.ownerUserId = ownerUserId;
    /** @type {string} */
    this.serverId = serverId;
    /** @type {string} — e.g. `https://192.168.4.20:3739` */
    this.redirectOrigin = redirectOrigin;
    /** @type {string} */
    this.scope = scope;
    /** @type {URL|null} — captured by redirectToAuthorization(). The route reads this back. */
    this.lastAuthorizationUrl = null;
  }

  /** @returns {string} */
  get redirectUrl() {
    return `${this.redirectOrigin}/api/mcp/oauth/callback`;
  }

  state() { return randomBytes(32).toString('base64url'); }

  get clientMetadata() {
    return {
      client_name: 'OpenEnsemble',
      client_uri: this.redirectOrigin,
      redirect_uris: [this.redirectUrl],
      grant_types: ['authorization_code', 'refresh_token'],
      response_types: ['code'],
      token_endpoint_auth_method: 'none',
      ...(this.scope ? { scope: this.scope } : {}),
    };
  }

  _file() {
    return path.join(USERS_DIR, this.ownerUserId, `mcp-oauth-${this.serverId}.json`);
  }

  _load() {
    const p = this._file();
    if (!fs.existsSync(p)) return {};
    try { return readEncryptedJsonFile(p); }
    catch (e) { console.warn(`[mcp-oauth] read ${p} failed:`, e.message); return {}; }
  }

  _save(data) {
    const p = this._file();
    fs.mkdirSync(path.dirname(p), { recursive: true });
    writeEncryptedJsonFile(p, data, { mode: 0o600 });
  }

  clientInformation() { return this._load().clientInformation; }

  saveClientInformation(info) {
    const data = this._load();
    data.clientInformation = info;
    this._save(data);
  }

  tokens() { return this._load().tokens; }

  saveTokens(t) {
    const data = this._load();
    data.tokens = t;
    this._save(data);
  }

  codeVerifier() {
    const v = this._load().codeVerifier;
    if (!v) throw new Error('PKCE code_verifier not found (start the OAuth flow first)');
    return v;
  }

  saveCodeVerifier(v) {
    const data = this._load();
    data.codeVerifier = v;
    this._save(data);
  }

  /**
   * Called by the SDK during the start phase. We can't actually redirect
   * the user (this is server-side code) — we capture the URL and let the
   * route hand it back to the browser to open.
   * @param {URL} url
   */
  redirectToAuthorization(url) {
    this.lastAuthorizationUrl = url;
  }
}

// ── Pending-state map for the callback route ──────────────────────────────────
// Maps the OAuth `state` parameter to the (userId, serverId) that initiated
// the flow. 10-min TTL — if the user takes longer to authorize, they re-start.
//
// Why in-memory (not encrypted file): the state token already comes back
// signed-with-PKCE-via-codeVerifier, so a leaked state token alone isn't
// useful without also reading the same user's encrypted oauth file. And
// the lifetime is short enough that server restart invalidating pending
// flows is acceptable (user just clicks Authorize again).
const _pending = new Map();
const PENDING_TTL_MS = 10 * 60 * 1000;

export function registerPendingState(state, payload) {
  // A new flow replaces the verifier for this server; old states cannot finish it.
  for (const [key, value] of _pending) {
    if (value.ownerUserId === payload.ownerUserId && value.serverId === payload.serverId) _pending.delete(key);
  }
  _pending.set(state, { ...payload, expiresAt: Date.now() + PENDING_TTL_MS });
}

export function peekPendingState(state) {
  const entry = _pending.get(state);
  if (!entry) return null;
  if (entry.expiresAt <= Date.now()) { _pending.delete(state); return null; }
  return entry;
}

export function consumePendingState(state) {
  const entry = peekPendingState(state);
  if (!entry) return null;
  _pending.delete(state);
  return entry;
}

// Periodically sweep expired entries so the map can't grow without bound.
setInterval(() => {
  const now = Date.now();
  for (const [k, v] of _pending) if (v.expiresAt < now) _pending.delete(k);
}, 60 * 1000).unref?.();

import fs from 'node:fs';
import path from 'node:path';
import { BASE_DIR } from './paths.mjs';
import { atomicWriteSync, withLock } from '../routes/_helpers/io-lock.mjs';

const CACHE_FILE = path.join(BASE_DIR, 'config', 'provider-model-documents.json');
const pending = new Map();
const TTL_MS = 6 * 60 * 60 * 1000;

function readCache() {
  try {
    const data = JSON.parse(fs.readFileSync(CACHE_FILE, 'utf8'));
    return data.version === 1 ? data.models ?? {} : {};
  } catch { return {}; }
}

/** Public structured model documentation only; never send account credentials. */
export async function documentedModelMetadata(provider, id, url, parse, { refresh = false } = {}) {
  const key = `${provider}/${id}`;
  const prior = readCache()[key];
  if (!refresh && prior && Date.now() - prior.checkedAt < (prior.failed ? 15 * 60_000 : TTL_MS)) return prior.metadata ?? null;
  if (pending.has(key)) return pending.get(key);
  const load = (async () => {
    let entry;
    try {
      const response = await fetch(url, {
        headers: { 'Accept-Language': 'en' }, redirect: 'error', signal: AbortSignal.timeout(5000),
      });
      if (!response.ok) { await response.body?.cancel(); throw new Error(`Model documentation HTTP ${response.status}`); }
      const reader = response.body.getReader();
      const chunks = [];
      let size = 0;
      try {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          size += value.length;
          if (size > 1024 * 1024) throw new Error('Model documentation exceeded size limit');
          chunks.push(Buffer.from(value));
        }
      } finally { await reader.cancel().catch(() => {}); }
      const metadata = parse(Buffer.concat(chunks).toString('utf8'), id, url);
      entry = { metadata, checkedAt: Date.now(), failed: false };
    } catch { entry = { ...prior, checkedAt: Date.now(), failed: true }; }
    await withLock(CACHE_FILE, () => {
      const models = readCache();
      models[key] = entry;
      fs.mkdirSync(path.dirname(CACHE_FILE), { recursive: true });
      atomicWriteSync(CACHE_FILE, JSON.stringify({ version: 1, models }, null, 2));
    });
    return entry.metadata ?? null;
  })();
  pending.set(key, load);
  try { return await load; } finally { pending.delete(key); }
}

/**
 * Shared retry helper for non-interactive agent runs.
 *
 * Call sites that need identical-shaped retry logic:
 *   • scheduler.mjs runTask                 — scheduled tasks (cron / one-shot)
 *   • lib/proposals.mjs runAcceptedAgent    — friction-as-proposer accepts
 *   • scheduler/watchers.mjs executeOnFire  — watcher-fired agent runs (single
 *                                             attempt by default, but uses the
 *                                             same error/stall classification)
 *
 * Failure shapes both must handle:
 *   1. streamChat yields {type:'error', message} — provider returned an
 *      explicit error event mid-stream.
 *   2. streamChat throws — fetch failed at the network layer, AsyncIterator
 *      raised before yielding anything. Without try/catch around the
 *      for-await, this would bypass retries entirely.
 *
 * `err.cause` is captured for fetch/AggregateError so failure messages
 * include the underlying network reason (ENOTFOUND, ECONNREFUSED, TLS,
 * etc.) instead of bare "fetch failed".
 */
import { scheduledContext } from './scheduled-context.mjs';
import { matchToolPlan } from './tool-plan-memory.mjs';
import { runInTaskContext } from './task-proxy-context.mjs';
import { iterateUntilAbort } from './abortable-async-iterator.mjs';
import { getTurnContext, runWithTurnContext } from './turn-abort-context.mjs';
import { isRetrySafeControlTool } from '../chat/recovery.mjs';
import { resourceLockConflictReport } from './task-resource-lock.mjs';

const DEFAULTS = {
  maxAttempts: 3,
  retryDelayMs: 30_000,
  context: 'agent',
};

// Abort a stream that makes NO progress (no events at all) for this long — the
// AbortController used to be created and never fired, so a hung provider stream
// would block a scheduled task forever. Generous so it never trips legit slow
// tools (which emit tool_progress events that reset the watchdog).
const STALL_MS = 300_000;
// Clearly-permanent failures — retrying maxAttempts × retryDelayMs changes
// nothing, so fail fast. Everything else is treated as transient and retried.
const NON_RETRIABLE_RE = /\b(api key|not set|not configured|no .{0,14}key|unauthorized|forbidden|invalid (?:model|api|key)|401|403)\b/i;

/**
 * @param {object} opts
 * @param {object} opts.scopedAgent     The agent record with id already scoped
 *                                      to `${userId}_${agentId}` for streaming.
 * @param {string} opts.userText        User-side prompt fed to streamChat.
 * @param {string} opts.systemNote      [SCHEDULED RUN] / [PROPOSAL ACCEPTED] /
 *                                      [WATCHER FIRED] — pinned to scheduledContext
 *                                      so nested ask_agent delegations inherit it.
 * @param {string} opts.userId
 * @param {Function} opts.streamChat    Imported by caller to avoid a circular import.
 * @param {number} [opts.maxAttempts=3]
 * @param {number} [opts.retryDelayMs=30000]
 * @param {string} [opts.context='agent']  Tag for log lines.
 * @param {string|null} [opts.rootTaskId] Stable identity for this detached
 *                                      logical run. Reused across retries so
 *                                      durable side-effect guards see every
 *                                      attempt as the same authorization.
 * @param {string|null} [opts.traceSource] Trace source for detached runs.
 * @param {boolean} [opts.originTaskManual=false] Whether this scheduled fire
 *                                      was an out-of-band Run-now invocation.
 * @param {object|null} [opts.taskContext] Durable owner for unattended runs
 *                                      that must await their real tool results.
 *                                      Scheduled mains deliberately omit this:
 *                                      their child barrier owns generic auto-bg.
 * @returns {Promise<{ succeeded, assistantContent, lastError }>}
 */
export async function runAgentWithRetry(opts) {
  const {
    scopedAgent, userText, systemNote, userId, streamChat,
    maxAttempts = DEFAULTS.maxAttempts,
    retryDelayMs = DEFAULTS.retryDelayMs,
    context = DEFAULTS.context,
    silent = false,
    isolatedTaskRun = true,
    originTaskId = null,
    originTaskOwnerId = null,
    originTaskAgent = null,
    originTaskLabel = null,
    originTaskRunId = null,
    originTaskManual = false,
    rootTaskId = originTaskRunId || originTaskId || null,
    traceSource = originTaskId ? 'scheduled' : null,
    taskContext = null,
  } = opts;

  const ownedTaskContext = taskContext && typeof taskContext === 'object'
    ? {
        ...taskContext,
        userId: taskContext.userId || userId,
        agentId: taskContext.agentId || scopedAgent.id,
        rootTaskId: taskContext.rootTaskId || rootTaskId || taskContext.taskId,
      }
    : null;

  let assistantContent = '';
  let lastError = null;
  let attempts = 0;
  let errorCode = null;
  let retryable = true;
  let toolInvoked = false;
  const resourceLockConflicts = new Map();

  const runAttempt = async (attempt) => {
    attempts = attempt;
    errorCode = null;
    retryable = true;
    let failed = false;
    let effectfulToolInvoked = false;
    assistantContent = '';
    try {
      await scheduledContext.run({
        scheduledNote: systemNote,
        originTaskId,
        originTaskOwnerId,
        originTaskAgent,
        taskLabel: originTaskLabel || userText,
        resourceLockConflicts,
        runId: originTaskRunId,
        manual: originTaskManual === true,
        silent: silent === true,
      }, async () => {
        const ac = new AbortController();
        // Stall watchdog: abort a stream that goes silent for STALL_MS. Reset on
        // every event so legit slow tools (which emit tool_progress) never trip it.
        let stallTimer = null;
        const armStall = () => {
          clearTimeout(stallTimer);
          stallTimer = setTimeout(() => {
            try { ac.abort(new Error(`Agent stream made no progress for ${STALL_MS / 1000}s`)); }
            catch { /* already terminal */ }
          }, STALL_MS);
        };
        const rememberedPlan = matchToolPlan(userId, { agentId: scopedAgent.id, phrase: userText });
        try {
          armStall();
          const consumeAttempt = async () => {
            for await (const event of iterateUntilAbort(streamChat(scopedAgent, userText, ac.signal, null, userId, null, systemNote, silent, null, {
              toolPlan: rememberedPlan,
              isolatedTaskRun,
              ...(rootTaskId ? { rootTaskId, traceSource: traceSource || context } : {}),
            }), ac.signal, 'Agent stream aborted')) {
              armStall();
              // Unknown and real tools may have committed a side effect, so
              // they block whole-turn retry. request_tools only expands this
              // attempt's in-memory schema and is safe to replay.
              if (event.type === 'tool_call' && !isRetrySafeControlTool(event.name)) {
                effectfulToolInvoked = true;
                toolInvoked = true;
              }
              if (event.type === 'error') {
                lastError = event.message || 'unknown provider error';
                errorCode = event.code || null;
                retryable = event.retryable !== false;
                if (event.code === 'persistence_failed' && typeof event.content === 'string') assistantContent = event.content;
                failed = true;
                break;
              }
              if (event.type === '__content') assistantContent = event.content;
            }
          };
          const inheritedTurnContext = getTurnContext() || {};
          await runWithTurnContext({ ...inheritedTurnContext, signal: ac.signal }, async () => {
            if (ownedTaskContext) await runInTaskContext(ownedTaskContext, consumeAttempt);
            else await consumeAttempt();
          });
        } finally {
          clearTimeout(stallTimer);
        }
      });
    } catch (e) {
      const causeMsg = e?.cause?.message || (e?.cause?.code ? `${e.cause.code}` : null);
      lastError = causeMsg ? `${e.message}: ${causeMsg}` : (e?.message || String(e));
      failed = true;
    }
    const lockReport = resourceLockConflictReport({ resourceLockConflicts });
    if (lockReport) {
      lastError = lockReport;
      assistantContent = [assistantContent, lockReport].filter(Boolean).join('\n\n');
      errorCode = 'RESOURCE_LOCKED';
      retryable = false;
      failed = true;
    }
    // LoopGuard stalls (chat/compress.mjs) yield a "Stopped: <reason>." token
    // without ever emitting type:'error', so the loop above doesn't flag them.
    // Without this check, a watcher/scheduled run that loops the same tool 4x
    // returns succeeded=true with empty-ish content — the caller has no signal
    // anything went wrong, no retry happens, and the user sees nothing.
    if (!failed) {
      const trimmed = (assistantContent || '').trim();
      if (/^Stopped:\s/.test(trimmed) && trimmed.length < 200) {
        lastError = trimmed.replace(/\.$/, '');
        failed = true;
      }
    }
    if (!failed) return true;
    // Only retry a transient failure where NO tool executed this attempt:
    // re-running the whole turn would re-fire any side-effecting tool
    // (email_send, an HA call, a purchase). Permanent errors fail fast.
    const permanent = !retryable || NON_RETRIABLE_RE.test(lastError || '');
    if (!effectfulToolInvoked && !permanent && attempt < maxAttempts) {
      console.log(`[${context}] attempt ${attempt}/${maxAttempts} failed (${lastError}); retrying in ${retryDelayMs / 1000}s`);
      return new Promise(resolve => setTimeout(() => resolve(runAttempt(attempt + 1)), retryDelayMs));
    }
    if (attempt < maxAttempts) {
      console.log(`[${context}] attempt ${attempt} failed (${lastError}); not retrying — ${effectfulToolInvoked ? 'a tool already ran (avoid double-execution)' : 'non-transient error'}`);
    }
    return false;
  };

  const succeeded = await runAttempt(1);
  return { succeeded, assistantContent, lastError: succeeded ? null : lastError, attempts, errorCode, toolInvoked };
}

/**
 * Embedding-based specialist router.
 *
 * Companion to the regex-based router in chat-dispatch.mjs. When regex misses,
 * we embed the user's message with the bundled nomic-embed model (~70MB, ~20ms
 * per query in-process) and find the nearest example phrase across all
 * specialist skills. If the match is confident and unambiguous, we route the
 * turn straight to that skill's owner — skipping the coordinator's reasoning entirely.
 *
 * Manifest field: each service skill can declare `intent_examples` — an array
 * of natural-language phrases that represent typical user requests for that
 * skill. Boot-time we embed every example once; per-turn we embed the user's
 * message and dot-product against all examples (already normalized, so dot =
 * cosine similarity).
 *
 * Tunables:
 *   - threshold: minimum cosine sim for a confident match. Default 0.72.
 *     Toggleable at runtime via /threshold N (in chat-dispatch).
 *   - gap: minimum margin between best and second-best skill. If two skills
 *     score within `gap` of each other, treat as ambiguous → fall through.
 *     Default 0.05.
 *
 * Returns null on:
 *   - cache not loaded
 *   - user not on coordinator
 *   - no example exceeds threshold
 *   - best skill within `gap` of second-best (ambiguous)
 */

import { embed } from '../memory/embedding.mjs';
import { listRoles, listAllRoles, getRoleAssignments } from '../roles.mjs';
import { stableAgentRef } from './agent-ref.mjs';

let _examples = []; // [{ skillId, name, phrase, vec }]
let _loaded = false;
let _vectorDimension = null;
// 0.78 default chosen empirically: catches most paraphrases (sim 0.80-0.95 for
// real intents) while keeping false positives like "what time is it" → gcal
// (sim 0.777) below threshold. Tune live via /threshold in chat.
let _threshold = 0.78;
const DEFAULT_GAP = 0.05;

function validateVector(vec, expectedDimension = null) {
  if (!Array.isArray(vec) || vec.length === 0) return { ok: false, reason: 'empty' };
  if (expectedDimension != null && vec.length !== expectedDimension) {
    return { ok: false, reason: 'dimension' };
  }
  let normSquared = 0;
  for (const value of vec) {
    if (typeof value !== 'number' || !Number.isFinite(value)) {
      return { ok: false, reason: 'malformed' };
    }
    normSquared += value * value;
    if (!Number.isFinite(normSquared)) return { ok: false, reason: 'malformed' };
  }
  if (!(normSquared > 0)) return { ok: false, reason: 'zero' };
  return { ok: true };
}

export async function loadIntentEmbeddings() {
  _loaded = false;
  const next = [];
  let skillCount = 0;
  const start = Date.now();
  // listAllRoles() (not listRoles()) so per-user custom skills with
  // intent_examples also get indexed. Each example is tagged with the owning
  // userId derived from manifest.createdBy (or null for global system skills),
  // and classifyByEmbedding filters out cross-user examples at query time so
  // user A's custom-skill phrases never match user B's prompts.
  const refused = { empty: 0, malformed: 0, zero: 0, dimension: 0 };
  let vectorDimension = null;
  for (const m of listAllRoles()) {
    if (!Array.isArray(m.intent_examples) || m.intent_examples.length === 0) continue;
    const ownerUserId = typeof m.createdBy === 'string' ? m.createdBy : null;
    skillCount++;
    for (const phrase of m.intent_examples) {
      if (typeof phrase !== 'string' || !phrase.trim()) continue;
      try {
        const vec = await embed(phrase);
        // embed() converts provider failures into zero vectors so callers do
        // not crash. Such vectors can never match a query, though, and storing
        // them makes a dead embedding provider look like a healthy loaded
        // index. Refuse and count them so the failure is operationally loud.
        const validation = validateVector(vec, vectorDimension);
        if (!validation.ok) {
          refused[validation.reason]++;
          continue;
        }
        if (vectorDimension == null) vectorDimension = vec.length;
        next.push({ skillId: m.id, name: m.name, phrase, vec, ownerUserId });
      } catch (e) {
        console.warn(`[embed-router] failed to embed example "${phrase}" for ${m.id}:`, e.message);
      }
    }
  }
  _examples = next;
  _vectorDimension = vectorDimension;
  _loaded = true;
  console.log(`[embed-router] loaded ${_examples.length} examples across ${skillCount} skills in ${Date.now() - start}ms`);
  const refusedTotal = Object.values(refused).reduce((sum, count) => sum + count, 0);
  if (refusedTotal > 0) {
    console.error(`[embed-router] REFUSED ${refusedTotal} invalid embedding examples (zero-norm=${refused.zero}, empty/non-array=${refused.empty}, non-numeric/non-finite=${refused.malformed}, dimension-mismatch=${refused.dimension}); embedding-based intent matching is degraded until the index is rebuilt with healthy vectors`);
  }
}

// Force a rebuild — call after a skill is added/removed/edited so new examples
// take effect without a server restart.
export function invalidateIntentEmbeddings() {
  _loaded = false;
  _examples = [];
  _vectorDimension = null;
}

export function getEmbedThreshold() { return _threshold; }
export function setEmbedThreshold(t) {
  const n = Number(t);
  if (!Number.isFinite(n) || n < 0 || n > 1) return false;
  _threshold = n;
  return true;
}

// Vectors come back from nomic-embed normalized (see memory/builtin-embed.mjs
// `normalize: true`), so dot product equals cosine similarity. No /(|a||b|).
function dot(a, b) {
  let s = 0;
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) s += a[i] * b[i];
  return s;
}

/**
 * Classify a user message against the loaded intent examples.
 * Returns { skillId, agentId, name, sim, phrase, strategy } or null.
 *
 * Only fires when:
 *   - currentAgentId matches the user's coordinator (don't surprise users in
 *     specialist chats)
 *   - exactly one skill clearly wins (sim ≥ threshold, gap to next ≥ gap)
 *   - that skill is assigned to a non-coordinator agent
 */
async function rankIntentSkillsByEmbedding(text, userId, currentAgentId, opts = {}) {
  if (!_loaded || _examples.length === 0) return null;
  if (typeof text !== 'string' || text.trim().length < 4) return null;

  const assignments = getRoleAssignments(userId);
  const coordAgentId = assignments?.coordinator;
  // currentAgentId guard: when set, must match the user's coordinator.
  // The tool-router calls with currentAgentId=null to mean "I am the
  // coordinator's pre-LLM trim — don't gate on the chat's agent."
  if (currentAgentId != null && (!coordAgentId || stableAgentRef(userId, currentAgentId) !== coordAgentId)) return null;

  // includeUnassigned: tool-router passes true so non-service skills like
  // `profiles` (which have no agent owner) can also win. Specialist-router
  // calls without it — for routing-to-a-specialist we need a real owner.
  const includeUnassigned = opts.includeUnassigned === true;
  const allowedSkillIds = opts.allowedSkillIds instanceof Set ? opts.allowedSkillIds : null;

  let queryVec;
  try { queryVec = await embed(text); }
  catch (e) { console.warn('[embed-router] query embed failed:', e.message); return null; }
  if (!validateVector(queryVec, _vectorDimension).ok) return null;

  // Best example per skill, ignoring skills not assigned (or owned by coord).
  // The literal "coordinator" string is an alias — resolve it first.
  //
  // For specialist routing (includeUnassigned=false), skills owned by the
  // coordinator are skipped — you don't delegate from yourself to yourself.
  // For TOOL routing (includeUnassigned=true), the opposite: a coordinator
  // holding e.g. oe-admin should match admin queries so the tool-router can
  // include the role's tools on this turn. Without this branch, oe-admin
  // examples were silently filtered out — every admin query missed the
  // classifier even with perfect-match examples in the manifest.
  const bestPerSkill = new Map();
  for (const ex of _examples) {
    // Per-user scoping: examples from user A's custom skills must NOT match
    // user B's prompts. ownerUserId === null means a global system skill,
    // which is shared by everyone.
    if (ex.ownerUserId && ex.ownerUserId !== userId) continue;
    if (allowedSkillIds && !allowedSkillIds.has(ex.skillId)) continue;
    const rawOwner = assignments[ex.skillId];
    let owner = null;
    if (rawOwner) {
      owner = rawOwner === 'coordinator' ? coordAgentId : rawOwner;
      if (owner === coordAgentId && !includeUnassigned) continue;
    } else if (!includeUnassigned || ex.ownerUserId) {
      // Built-in unassigned skills may participate in coordinator tool
      // routing. A user-created skill with no assignment means exactly what
      // Settings says: no agent can use it, including via dynamic expansion.
      continue;
    }
    const sim = dot(queryVec, ex.vec);
    if (!Number.isFinite(sim)) continue;
    const cur = bestPerSkill.get(ex.skillId);
    if (!cur || sim > cur.sim) {
      bestPerSkill.set(ex.skillId, { sim, agentId: owner, name: ex.name, phrase: ex.phrase });
    }
  }
  if (bestPerSkill.size === 0) return [];

  // Rank skills by their best example similarity.
  const ranked = [...bestPerSkill.entries()]
    .map(([skillId, b]) => ({ skillId, ...b }))
    .sort((a, b) => b.sim - a.sim);
  return ranked.map(hit => ({ ...hit, strategy: 'embed' }));
}

/**
 * Return the best embedding hit per skill, sorted by similarity. This is a
 * diagnostic/building-block API; callers still choose their own threshold,
 * ambiguity band, and maximum candidate count.
 */
export async function rankByEmbedding(text, userId, currentAgentId, opts = {}) {
  return await rankIntentSkillsByEmbedding(text, userId, currentAgentId, opts) ?? [];
}

/**
 * Classify one unambiguous winner. Preserves the specialist-router contract;
 * the coordinator tool router may use rankByEmbedding for bounded ambiguity
 * expansion without weakening this stricter delegation path.
 */
export async function classifyByEmbedding(text, userId, currentAgentId, opts = {}) {
  const ranked = await rankIntentSkillsByEmbedding(text, userId, currentAgentId, opts);
  if (!ranked?.length) return null;
  const threshold = typeof opts.threshold === 'number' ? opts.threshold : _threshold;
  const gap = typeof opts.gap === 'number' ? opts.gap : DEFAULT_GAP;
  const top = ranked[0];
  if (top.sim < threshold) return null;

  // Disambiguation: if the next-best skill is within `gap`, it's a tie — fall
  // through so the LLM can clarify rather than guess wrong.
  const second = ranked[1];
  if (second && (top.sim - second.sim) < gap) return null;

  return top;
}

/**
 * Narrow rate limits for the unauthenticated browser-pairing surface.
 *
 * The server-wide /api limiter still applies. These counters additionally
 * bound pairing requests and bad claim-secret guesses even when the route is
 * mounted outside the full server in tests or reused by another HTTP entry.
 * A valid claim is never blocked by an IP lockout: legitimate clients behind
 * a shared NAT must not be stranded by somebody else's bad guesses.
 */

const WINDOW_MS = 10 * 60 * 1000;
const MAX_REQUESTS_PER_IP = 10;
const MAX_BAD_CLAIMS_PER_IP = 10;
const GLOBAL_WINDOW_MS = 60 * 60 * 1000;
const MAX_GLOBAL_BAD_CLAIMS = 500;

const requestBuckets = new Map();
const claimBuckets = new Map();
let globalBadClaims = 0;
let globalWindowStartedAt = Date.now();

function consume(bucket, key, limit, now = Date.now()) {
  const current = bucket.get(key);
  if (!current || now - current.startedAt >= WINDOW_MS) {
    bucket.set(key, { count: 1, startedAt: now });
    return true;
  }
  if (current.count >= limit) return false;
  current.count++;
  return true;
}

function isLocked(bucket, key, limit, now = Date.now()) {
  const current = bucket.get(key);
  if (!current) return false;
  if (now - current.startedAt >= WINDOW_MS) {
    bucket.delete(key);
    return false;
  }
  return current.count >= limit;
}

function resetGlobalIfNeeded(now = Date.now()) {
  if (now - globalWindowStartedAt >= GLOBAL_WINDOW_MS) {
    globalWindowStartedAt = now;
    globalBadClaims = 0;
  }
}

export function consumeBrowserPairingRequest(ip) {
  return consume(requestBuckets, String(ip || 'unknown'), MAX_REQUESTS_PER_IP);
}

export function isBrowserClaimLocked(ip) {
  resetGlobalIfNeeded();
  return globalBadClaims >= MAX_GLOBAL_BAD_CLAIMS
    || isLocked(claimBuckets, String(ip || 'unknown'), MAX_BAD_CLAIMS_PER_IP);
}

export function recordBadBrowserClaim(ip) {
  resetGlobalIfNeeded();
  consume(claimBuckets, String(ip || 'unknown'), MAX_BAD_CLAIMS_PER_IP);
  globalBadClaims++;
}

export function clearBadBrowserClaims(ip) {
  claimBuckets.delete(String(ip || 'unknown'));
}

setInterval(() => {
  const cutoff = Date.now() - WINDOW_MS;
  for (const bucket of [requestBuckets, claimBuckets]) {
    for (const [key, entry] of bucket) {
      if (entry.startedAt <= cutoff) bucket.delete(key);
    }
  }
  resetGlobalIfNeeded();
}, 60_000).unref?.();

export function _resetBrowserPairingRateLimitsForTests() {
  requestBuckets.clear();
  claimBuckets.clear();
  globalBadClaims = 0;
  globalWindowStartedAt = Date.now();
}

{
  "name": "oe-node-agent",
  "version": "1.0.0",
  "description": "OpenEnsemble Remote Node Agent — lightweight client for remote machine management",
  "type": "module",
